def pasar_datos(apps, schema_editor):
    """Los avisos ya enviados pasan a la tabla nueva (para no repetirlos) y los permisos del monitoreo se retiran:
    quien podía configurar el monitoreo (Tecnología, Administrador del sistema) pasa a manejar los equipos y activos."""
    Nueva = apps.get_model('core', 'AlertaEnviada')
    try:
        Vieja = apps.get_model('monitoreo', 'AlertaEnviada')
    except LookupError:
        Vieja = None
    if Vieja is not None:
        existentes = set(Nueva.objects.values_list('usuario_id', 'clave'))
        lote = [Nueva(usuario_id=a.usuario_id, clave=a.clave, tipo=a.tipo, detalle=a.detalle) for a in Vieja.objects.all()
                if (a.usuario_id, a.clave) not in existentes]
        Nueva.objects.bulk_create(lote, batch_size=500, ignore_conflicts=True)
    Perfil = apps.get_model('core', 'PermisosDePerfil')
    for p in Perfil.objects.all():
        lista = list(p.permisos or [])
        nueva = [c for c in lista if c not in VIEJOS]
        if 'monitoreo.configurar' in lista and 'activos.gestionar' not in nueva:
            nueva.append('activos.gestionar')
        if nueva != lista:
            p.permisos = nueva
            p.save(update_fields=['permisos'])
    Excepcion = apps.get_model('core', 'ExcepcionPermiso')
    for e in Excepcion.objects.filter(permiso='monitoreo.configurar', conceder=True):
        if not Excepcion.objects.filter(usuario_id=e.usuario_id, permiso='activos.gestionar').exists():
            Excepcion.objects.create(usuario_id=e.usuario_id, permiso='activos.gestionar', conceder=True)
    Excepcion.objects.filter(permiso__in=VIEJOS).delete()


